function IsPrime(N: integer): boolean;
begin
  if N <= 1 then
  begin
    IsPrime := False;
    exit;
  end;
  if (N = 2) or (N = 3) then
  begin
    IsPrime := True;
    exit;
  end;
  if (N mod 2 = 0) or (N mod 3 = 0) then
  begin
    IsPrime := False;
    exit;
  end;

  var Step := 4;
  var Divisor := 5;
  while Int64(Divisor) * Divisor <= N do
  begin
    if N mod Divisor = 0 then
    begin
      IsPrime := False;
      exit;
    end;
    Divisor += Step;
    Step := 6 - Step; // alternate between +2 and +4: 6k-1, 6k+1
  end;

  IsPrime := True;
end;

