  Shuffler = static class
  public
    class procedure ShuffleArray(Arr: array of integer);
    begin
      // Seed is based on the contents of the array
      var Seed := 0;
      foreach var Item in Arr do
        Seed := Seed xor Item;

      if Seed = 0 then
        Seed := 1234567;

      var N := Arr.Length;
      // Fisher–Yates shuffle
      for var I := N - 1 downto 1 do
      begin
        // Simple LCG
        Seed := (Seed * 1103515245 + 12345) and $7FFFFFFF;
        var J := Seed mod (I + 1);

        var Temp := Arr[I];
        Arr[I] := Arr[J];
        Arr[J] := Temp;
      end;
    end;
  end;

