function TryParseInteger(InputText: string; var ParsedValue: int64): boolean;
begin
  if InputText = nil then
  begin
    TryParseInteger := False;
    exit;
  end;

  var S := InputText.Trim;
  if S = '' then
  begin
    TryParseInteger := False;
    exit;
  end;

  var Sign := 1;
  var Index := 1;

  if (S[1] = '+') or (S[1] = '-') then
  begin
    if S[1] = '-' then
      Sign := -1;
    Index := 2;
    if Index > S.Length then
    begin
      TryParseInteger := False;
      exit;
    end;
  end;

  var Value: int64 := 0;
  while Index <= S.Length do
  begin
    var Ch := S[Index];
    if not System.Char.IsDigit(Ch) then
    begin
      TryParseInteger := False;
      exit;
    end;

    var Digit := Ord(Ch) - Ord('0');

    // Check for overflow before updating Value
    if Sign = 1 then
    begin
      if (Value > int64.MaxValue div 10) or
         ((Value = int64.MaxValue div 10) and (Digit > int64.MaxValue mod 10)) then
      begin
        TryParseInteger := False;
        exit;
      end;
    end
    else
    begin
      if (-Value < int64.MinValue div 10) or
         ((-Value = int64.MinValue div 10) and (Digit > -(int64.MinValue mod 10))) then
      begin
        TryParseInteger := False;
        exit;
      end;
    end;

    Value := Value * 10 + Digit;
    Index += 1;
  end;

  ParsedValue := Sign * Value;
  TryParseInteger := True;
end;

begin
  var Samples := Arr('42', '  -17 ', 'abc', '9223372036854775808');

  foreach var S in Samples do
  begin
    var V: int64;
    if TryParseInteger(S, V) then
      Println($'"{S}" is a valid integer: {V}')
    else
      Println($'"{S}" is NOT a valid integer');
  end;
end.

