end.

type
  SortStats = record
    Comparisons: int64;
    Swaps: int64;
  end;

procedure InsertionSort(var Arr: array of integer; var Stats: SortStats);
begin
  Stats.Comparisons := 0;
  Stats.Swaps := 0;

  for var I := 1 to Arr.Length - 1 do
  begin
    var Key := Arr[I];
    var J := I - 1;
    while (J >= 0) and (Arr[J] > Key) do
    begin
      Stats.Comparisons += 1;
      Arr[J + 1] := Arr[J];
      Stats.Swaps += 1;
      J -= 1;
    end;
    if J >= 0 then
      Stats.Comparisons += 1;
    Arr[J + 1] := Key;
  end;
end;

begin
  var Numbers := Arr(12, 4, 5, 3, 8, 7);
  var Stats: SortStats;

  Println('Original array: ', Numbers);
  InsertionSort(Numbers, Stats);
  Println('Sorted array: ', Numbers);
  Println($'Comparisons: {Stats.Comparisons}, Swaps: {Stats.Swaps}');
end.

