uses System, System.Collections.Generic;

type
  EventHandlerDelegate<TEventArgs> = procedure(Sender: object; Args: TEventArgs);

  EventListener<TEventArgs> = class
  private
    LockObject: object := new object;
    EventHandlers: Dictionary<Guid, EventHandlerDelegate<TEventArgs>> := new Dictionary<Guid, EventHandlerDelegate<TEventArgs>>;
    EventPriorities: Dictionary<Guid, integer> := new Dictionary<Guid, integer>;
    CanceledEvents: HashSet<Guid> := new HashSet<Guid>;
    TotalEventsFired: integer := 0;
  public
    function Subscribe(Handler: EventHandlerDelegate<TEventArgs>; Priority: integer := 0): Guid;
    begin
      var Id := Guid.NewGuid;
      lock LockObject do
      begin
        EventHandlers.Add(Id, Handler);
        EventPriorities.Add(Id, Priority);
      end;
      Subscribe := Id;
    end;

    procedure Unsubscribe(Id: Guid);
    begin
      lock LockObject do
      begin
        EventHandlers.Remove(Id);
        EventPriorities.Remove(Id);
        CanceledEvents.Remove(Id);
      end;
    end;

    procedure SetPriority(Id: Guid; Priority: integer);
    begin
      lock LockObject do
        if EventPriorities.ContainsKey(Id) then
          EventPriorities[Id] := Priority;
    end;

    function GetPriority(Id: Guid): integer;
    begin
      lock LockObject do
        if EventPriorities.ContainsKey(Id) then
          GetPriority := EventPriorities[Id]
        else
          GetPriority := 0;
    end;

    procedure CancelEvent(Id: Guid);
    begin
      lock LockObject do
        CanceledEvents.Add(Id);
    end;

    function IsCanceled(Id: Guid): boolean;
    begin
      lock LockObject do
        IsCanceled := CanceledEvents.Contains(Id);
    end;

    function GetCanceledEvents: List<Guid>;
    begin
      lock LockObject do
        GetCanceledEvents := new List<Guid>(CanceledEvents);
    end;

    procedure ClearCanceledEvents;
    begin
      lock LockObject do
        CanceledEvents.Clear;
    end;

    procedure ClearSubscribedEvents;
    begin
      lock LockObject do
      begin
        EventHandlers.Clear;
        EventPriorities.Clear;
        CanceledEvents.Clear;
      end;
    end;

    function GetSubscribedEventIds: List<Guid>;
    begin
      lock LockObject do
        GetSubscribedEventIds := new List<Guid>(EventHandlers.Keys);
    end;

    function GetSubscribedCount: integer;
    begin
      lock LockObject do
        GetSubscribedCount := EventHandlers.Count;
    end;

    function GetTotalEventsFired: integer;
    begin
      GetTotalEventsFired := TotalEventsFired;
    end;

    procedure Fire(Sender: object; Args: TEventArgs);
    begin
      var SnapshotHandlers: List<KeyValuePair<Guid, EventHandlerDelegate<TEventArgs>>>;
      lock LockObject do
      begin
        SnapshotHandlers := new List<KeyValuePair<Guid, EventHandlerDelegate<TEventArgs>>>(EventHandlers);
      end;

      // Sort by priority (higher first)
      SnapshotHandlers.Sort(
        (p1, p2) ->
        begin
          var Pri1 := GetPriority(p1.Key);
          var Pri2 := GetPriority(p2.Key);
          Result := Pri2.CompareTo(Pri1);
        end);

      foreach var Pair in SnapshotHandlers do
      begin
        if IsCanceled(Pair.Key) then
          continue;
        Pair.Value(Sender, Args);
      end;

      System.Threading.Interlocked.Increment(TotalEventsFired);
    end;
