function Factorial(N: integer): int64;
begin
  if N < 0 then
    raise new ArgumentException('Factorial is not defined for negative numbers.');

  if (N = 0) or (N = 1) then
  begin
    Factorial := 1;
    exit;
  end;

  // Recursive call: depth is proportional to N
  Factorial := N * Factorial(N - 1);
end;

