function RandomLowercaseLetter(Rnd: Random): char;
begin
  var Code := Rnd.Next(Ord('a'), Ord('z') + 1);
  RandomLowercaseLetter := Chr(Code);
end;

function RandomDigit(Rnd: Random): char;
begin
  var Code := Rnd.Next(Ord('0'), Ord('9') + 1);
  RandomDigit := Chr(Code);
end;

function GenerateRandomString(LengthValue: integer): string;
begin
  if LengthValue <= 0 then
    raise new ArgumentException('Length must be positive.');

  var Rnd := new Random;
  var Chars := new char[LengthValue];

  // First character must be a lowercase letter
  Chars[0] := RandomLowercaseLetter(Rnd);

  for var Index := 1 to LengthValue - 1 do
  begin
    var Choice := Rnd.Next(0, 2); // 0: letter, 1: digit
    if Choice = 0 then
      Chars[Index] := RandomLowercaseLetter(Rnd)
    else
      Chars[Index] := RandomDigit(Rnd);
  end;

  GenerateRandomString := new string(Chars);
end;

