function IsPrime(X: integer): boolean;
begin
  if X < 2 then
  begin
    IsPrime := False;
    exit;
  end;

  if (X = 2) or (X = 3) then
  begin
    IsPrime := True;
    exit;
  end;

  if (X mod 2 = 0) or (X mod 3 = 0) then
  begin
    IsPrime := False;
    exit;
  end;

  var Divisor := 5;
  var Step := 2;
  while int64(Divisor) * Divisor <= X do
  begin
    if X mod Divisor = 0 then
    begin
      IsPrime := False;
      exit;
    end;
    Divisor += Step;
    Step := 6 - Step; // check numbers of the form 6k ± 1
  end;

  IsPrime := True;
end;

