function ToBinaryString(Value: int64): string;
begin
  if Value = 0 then
  begin
    ToBinaryString := '0';
    exit;
  end;

  var IsNegative := Value < 0;
  if IsNegative then
    Value := -Value;

  var Bits := '';
  while Value > 0 do
  begin
    var Bit := Value mod 2;
    Bits := Chr(Ord('0') + Bit) + Bits;
    Value := Value div 2;
  end;

  if IsNegative then
    ToBinaryString := '-' + Bits
  else
    ToBinaryString := Bits;
end;

