function TriangleArea(A, B, C: real): real;
begin
  if (A <= 0) or (B <= 0) or (C <= 0) then
    raise new ArgumentException('Side lengths must be positive.');

  if (A + B <= C) or (A + C <= B) or (B + C <= A) then
    raise new ArgumentException('The given sides do not form a valid triangle.');

  var S := (A + B + C) / 2.0;
  var AreaSquared := S * (S - A) * (S - B) * (S - C);
  if AreaSquared < 0 then
    raise new ArgumentException('Numerical error while computing area.');

  TriangleArea := System.Math.Sqrt(AreaSquared);
end;

procedure TestTriangle(A, B, C: real);
begin
  try
    var Area := TriangleArea(A, B, C);
    Println($'Triangle({A}, {B}, {C}) area = {Area:0.000}');
  except
    on E: Exception do
      Println($'Triangle({A}, {B}, {C}) error: {E.Message}');
  end;
end;

begin
