function IsValidString(S: string): boolean;
begin
  if string.IsNullOrWhiteSpace(S) then
  begin
    IsValidString := False;
    exit;
  end;

  var UpperCount := 0;
  var DigitCount := 0;
  var SpecialCount := 0;

  foreach var Ch in S do
  begin
    if System.Char.IsUpper(Ch) then
      UpperCount += 1;
    if System.Char.IsDigit(Ch) then
      DigitCount += 1;
    if not (System.Char.IsLetterOrDigit(Ch) or char.IsWhiteSpace(Ch)) then
      SpecialCount += 1;
  end;

  // Example constraints (can be adjusted):
  // exactly one uppercase letter, at least one digit, exactly two special characters
  IsValidString := (UpperCount = 1) and (DigitCount >= 1) and (SpecialCount = 2);
end;

begin
  Print('Enter N (number of strings): ');
  var N := ReadInteger;

  var Items := new List<string>;
  for var Index := 1 to N do
  begin
    while True do
    begin
      Print($'Enter string #{Index}: ');
      var S := ReadString;
      if IsValidString(S) then
      begin
        Items.Add(S);
        break;
      end
      else
        Println('Invalid string: must contain exactly one uppercase letter, at least one digit, and exactly two special characters.');
    end;
  end;

  // Sort by number of special characters (descending),
  // then by string (descending) within groups
  Items.Sort(
    (a, b) ->
    begin
      var Ca := CountSpecialCharacters(a);
      var Cb := CountSpecialCharacters(b);
      if Ca <> Cb then
        Result := Cb.CompareTo(Ca)
      else
        Result := string.Compare(b, a, StringComparison.Ordinal);
    end);

  Println;
  Println('Sorted list:');
  for var I := 0 to Items.Count - 1 do
    Println($'{I}: {Items[I]} (special chars = {CountSpecialCharacters(Items[I])})');

