type
  InvalidInterestRateException = class(System.Exception)
  end;

  InvalidNumberOfYearsException = class(System.Exception)
  end;

  IncompleteDataException = class(System.Exception)
  end;

  CompoundInterestCalculator = class
  private
    fPrincipalAmount: real;
    fInterestRate: real;
    fNumberOfYears: integer;
  public
    constructor(principalAmount, interestRate: real; numberOfYears: integer);
    begin
      if principalAmount <= 0 then
        raise new System.ArgumentException('Principal amount must be positive');

      PrincipalAmount := principalAmount;
      InterestRate := interestRate;
      NumberOfYears := numberOfYears;
    end;

    procedure SetPrincipalAmount(value: real);
    begin
      if value <= 0 then
        raise new System.ArgumentException('Principal amount must be positive');
      fPrincipalAmount := value;
    end;

    procedure SetInterestRate(value: real);
    begin
      if (value < 0) or (value > 0.1) then
        raise new InvalidInterestRateException('Interest rate must be between 0 and 10%');
      fInterestRate := value;
    end;

    procedure SetNumberOfYears(value: integer);
    begin
      if value <= 0 then
        raise new InvalidNumberOfYearsException('Number of years must be a positive integer');
      fNumberOfYears := value;
    end;

    property PrincipalAmount: real read fPrincipalAmount write SetPrincipalAmount;
    property InterestRate: real read fInterestRate write SetInterestRate;
    property NumberOfYears: integer read fNumberOfYears write SetNumberOfYears;

    function CalculateInterest(): real;
    begin
      Result := PrincipalAmount * Power(1 + InterestRate, NumberOfYears) - PrincipalAmount;
    end;

    function CalculateTotalAmount(): real;
    begin
      Result := PrincipalAmount + CalculateInterest();
    end;

    function CalculateMonthlyPayment(): real;
    begin
      if (PrincipalAmount <= 0) or (InterestRate <= 0) or (NumberOfYears <= 0) then
        raise new IncompleteDataException('Principal amount, interest rate, and number of years must be set');

      Result := CalculateTotalAmount() / (NumberOfYears * 12);
    end;
  end;

begin
  var calculator := new CompoundInterestCalculator(1000, 0.05, 3);

  var interestAmount := calculator.CalculateInterest();
  Println('Compound interest amount: ', interestAmount);

  calculator.PrincipalAmount := 2000;
  var newInterestAmount := calculator.CalculateInterest();
  Println('Updated compound interest amount: ', newInterestAmount);

  var totalAmount := calculator.CalculateTotalAmount();
  Println('Total amount: ', totalAmount);

  var monthlyPayment := calculator.CalculateMonthlyPayment();
  Println('Monthly payment: ', monthlyPayment);
end.

