function ConvertToWords(number: int64): string;
begin
  if number = 0 then
    Result := 'zero'
  else if number < 0 then
    Result := 'minus ' + ConvertToWords(Abs(number))
  else
  begin
    var words := '';

    if (number div 1000000000000) > 0 then
    begin
      words += ConvertToWords(number div 1000000000000) + ' trillion ';
      number := number mod 1000000000000;
    end;

    if (number div 1000000000) > 0 then
    begin
      words += ConvertToWords(number div 1000000000) + ' billion ';
      number := number mod 1000000000;
    end;

    if (number div 1000000) > 0 then
    begin
      words += ConvertToWords(number div 1000000) + ' million ';
      number := number mod 1000000;
    end;

    if (number div 1000) > 0 then
    begin
      words += ConvertToWords(number div 1000) + ' thousand ';
      number := number mod 1000;
    end;

    if (number div 100) > 0 then
    begin
      words += ConvertToWords(number div 100) + ' hundred ';
      number := number mod 100;
    end;

    if number > 0 then
    begin
      if words <> '' then
        words += 'and ';

      var units := Arr('', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 
                     'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 
                     'seventeen', 'eighteen', 'nineteen');
      var tens := Arr('', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 
                    'eighty', 'ninety');

      if number < 20 then
        words += units[number]
      else
      begin
        words += tens[number div 10];
        if (number mod 10) > 0 then
          words += '-' + units[number mod 10];
      end;
    end;

    Result := words.Trim;
  end;
end;

