    ('French', Lst('Bonjour!', 'Bonsoir!')),
    ('Spanish', Lst('¡Buenos días!', '¡Buenas tardes!', '¡Buenas noches!'))
  );
end;

procedure MainForm.LoadCustomizedMessages();
begin
  try
    var json := &File.ReadAllText('customized_messages.json');
    customizedMessages := JsonConvert.DeserializeObject<Dictionary&<string, List<string>>>(json);
  except
    on &FileNotFoundException do
      customizedMessages := new Dictionary<string, List<string>>();
    on ex: Exception do
    begin
      MessageBox.Show('Error loading customized messages: ' + ex.Message);
      customizedMessages := new Dictionary<string, List<string>>();
    end;
  end;
end;

procedure MainForm.SaveCustomizedMessages();
begin
  try
    var json := JsonConvert.SerializeObject(customizedMessages, Formatting.Indented);
