function MainForm.GenerateRandomWelcomeMessage(): string;
begin
  var random := new Random();
  Result := welcomeMessages[random.Next(welcomeMessages.Count)];
end;

procedure MainForm.UpdateWelcomeMessage(message: string);
begin
  if InvokeRequired then
    Invoke(procedure -> UpdateWelcomeMessage(message))
  else
    welcomeLabel.Text := message;
end;

procedure MainForm.GenerateWelcomeMessage();
begin
  while true do
  begin
    tokenSource.Token.ThrowIfCancellationRequested();

    var message := GenerateRandomWelcomeMessage();
    UpdateWelcomeMessage(message);

    Sleep(5000);
  end;
end;

procedure MainForm.ChangeLanguage(language: string);
begin
  if not predefinedMessages.ContainsKey(language) then
  begin
    MessageBox.Show('Unsupported language selected.');
    exit;
  end;

  messageComboBox.Items.Clear();
  messageComboBox.Items.AddRange(predefinedMessages[language].ToArray());
  messageComboBox.SelectedIndex := 0;
end;

procedure MainForm.SearchMessages(keyword: string);
begin
  var searchResults := customizedMessages
    .Where(pair -> pair.Value.Any(message -> message.Contains(keyword, StringComparison.OrdinalIgnoreCase)))
    .ToDictionary(pair -> pair.Key, pair -> pair.Value);

  if searchResults.Count = 0 then
  begin
    MessageBox.Show('No matching messages found.');
    exit;
  end;

  resultListBox.Items.Clear();
  foreach var pair in searchResults do
    resultListBox.Items.Add(pair.Key + ': ' + string.Join(', ', pair.Value));
end;

