begin
  var language := languageComboBox.SelectedItem.ToString();
  var newMessage := messageTextBox.Text;

  if string.IsNullOrWhiteSpace(newMessage) then
  begin
    MessageBox.Show('Please enter a valid message.');
    exit;
  end;

  if not customizedMessages.ContainsKey(language) then
    customizedMessages.Add(language, new List<string>());

  customizedMessages[language].Add(newMessage);

  MessageBox.Show('Message added successfully.');
  messageTextBox.Clear();
end;

procedure MainForm.removeButton_Click(sender: object; e: EventArgs);
begin
  var language := languageComboBox.SelectedItem.ToString();
  var selectedMessage := messageComboBox.SelectedItem.ToString();

  if not customizedMessages.ContainsKey(language) then
  begin
    MessageBox.Show('No customized messages found for the selected language.');
    exit;
  end;

  if not customizedMessages[language].Contains(selectedMessage) then
  begin
    MessageBox.Show('The selected message does not exist.');
    exit;
  end;

  customizedMessages[language].Remove(selectedMessage);

  MessageBox.Show('Message removed successfully.');
  messageComboBox.Items.Remove(selectedMessage);
  if messageComboBox.Items.Count > 0 then
    messageComboBox.SelectedIndex := 0;
