uses
  System.Numerics;

function FindRoots(coefficients: array of Complex): array of Complex;
begin
  if coefficients.Length <> 5 then
    raise new ArgumentException('The coefficients array must contain exactly five elements.');

  var roots := new Complex[4];

  var a := coefficients[4];
  var b := coefficients[3];
  var c := coefficients[2];
  var d := coefficients[1];
  var e := coefficients[0];

  var p := (8 * a * c - 3 * b * b) / (8 * a * a);
  var q := (b * b * b - 4 * a * b * c + 8 * a * a * d) / (8 * a * a * a);
  var r := (-3 * b * b * b * b + 256 * a * a * a * e - 64 * a * a * b * d + 16 * a * b * b * c) / (256 * a * a * a * a);

  var discriminant := q * q - 4 * p * p * p - 4 * r * r * p + 18 * p * q * r - 27 * r * r * r;

  if discriminant = Complex.Zero then
  begin
    var discriminant0 := q * q - 4 * p * p * p;
    var discriminant1 := 18 * p * q * r - 27 * r * r * r;

    if (discriminant0 = Complex.Zero) and (discriminant1 = Complex.Zero) then
    begin
      // All roots are zero (repeated roots)
      roots[0] := Complex.Zero;
      roots[1] := Complex.Zero;
      roots[2] := Complex.Zero;
      roots[3] := Complex.Zero;
    end
    else if discriminant0 = Complex.Zero then
    begin
      // Two repeated roots and two zero roots
      roots[0] := -q / (4 * p);
      roots[1] := -q / (4 * p);
      roots[2] := Complex.Zero;
      roots[3] := Complex.Zero;
    end
    else
    begin
      // Two repeated roots and two zero roots
      roots[0] := (-q + Complex.Sqrt(discriminant1)) / (4 * p);
      roots[1] := (-q + Complex.Sqrt(discriminant1)) / (4 * p);
      roots[2] := (-q - Complex.Sqrt(discriminant1)) / (4 * p);
      roots[3] := (-q - Complex.Sqrt(discriminant1)) / (4 * p);
    end;
  end
  else if discriminant.Real > 0 then
  begin
    var sqrtDiscriminant := Complex.Sqrt(discriminant);

    var cubeRoot1 := (q + sqrtDiscriminant) / 2;
    var cubeRoot2 := (q - sqrtDiscriminant) / 2;

    var root1 := Complex.Pow(cubeRoot1, 1.0 / 3.0);
    var root2 := Complex.Pow(cubeRoot2, 1.0 / 3.0);

    roots[0] := -b / (4 * a) + root1 + root2;
    roots[1] := -b / (4 * a) - 0.5 * (root1 + root2) + Complex.ImaginaryOne * 0.5 * Sqrt(3) * (root1 - root2);
    roots[2] := -b / (4 * a) - 0.5 * (root1 + root2) - Complex.ImaginaryOne * 0.5 * Sqrt(3) * (root1 - root2);
    roots[3] := -b / (4 * a) - root1 - root2;
  end
  else if discriminant.Real < 0 then
  begin
    var sqrtDiscriminant := Complex.Sqrt(-discriminant);
    var phi := 1.0 / 3.0 * Complex.Acos(-q / (2 * p) * Complex.Sqrt(-27 / p));

    roots[0] := -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos(phi / 3);
    roots[1] := -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos((phi + 2 * Pi) / 3);
    roots[2] := -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos((phi + 4 * Pi) / 3);
    roots[3] := -b / (4 * a);
  end;

  Result := roots;
end;

begin
  var coefficients := Arr(
    new Complex(1, 0), // a
    new Complex(0, 2), // b
    new Complex(3, 0), // c
    new Complex(0, -4), // d
    new Complex(5, 0) // e
  );

  var roots := FindRoots(coefficients);

  Println('Roots:');
  foreach var root in roots do
    Println(root);
end.

