type
  Node = class
  public
    Payload: string;
    Left: Node;
    Right: Node;

    constructor Create(payload: string);
    begin
      Payload := payload;
      Left := nil;
      Right := nil;
    end;
  end;

  BinarySearchTree = class
  private
    Root: Node;

    procedure InOrderTraversal(node: Node);

  public
    constructor Create();
    begin
      Root := nil;
    end;

    procedure Insert(payload: string);
    procedure Print();
  end;

procedure BinarySearchTree.Insert(payload: string);
begin
  if Root = nil then
  begin
    Root := new Node(payload);
    exit;
  end;

  var currentNode := Root;

  while true do
  begin
    if string.Compare(payload, currentNode.Payload) < 0 then
    begin
      if currentNode.Left = nil then
      begin
        currentNode.Left := new Node(payload);
        break;
      end
      else
        currentNode := currentNode.Left;
    end
    else if string.Compare(payload, currentNode.Payload) > 0 then
    begin
      if currentNode.Right = nil then
      begin
        currentNode.Right := new Node(payload);
        break;
      end
      else
        currentNode := currentNode.Right;
    end
    else
    begin
      // Handle duplicates by discarding them
      break;
    end;
  end;
end;

procedure BinarySearchTree.InOrderTraversal(node: Node);
begin
  if node <> nil then
  begin
    InOrderTraversal(node.Left);
    Println(node.Payload);
    InOrderTraversal(node.Right);
  end;
end;

