function FindThirdCommonElement(array1, array2: array of integer): integer;
begin
  var counter1 := 0;
  var counter2 := 0;

  var firstCommon := integer.MaxValue;
  var secondCommon := integer.MaxValue;
  var thirdCommon := integer.MaxValue;

  // Process first array
  for var i := 0 to array1.Length - 1 do
  begin
    if counter1 = 0 then
    begin
      firstCommon := array1[i];
      counter1 += 1;
    end
    else if array1[i] = firstCommon then
      counter1 += 1
    else if counter2 = 0 then
    begin
      secondCommon := array1[i];
      counter2 += 1;
    end
    else if array1[i] = secondCommon then
      counter2 += 1
    else
    begin
      counter1 -= 1;
      counter2 -= 1;
    end;
  end;

  // Reset counters for second array
  counter1 := 0;
  counter2 := 0;

  // Process second array
  for var i := 0 to array2.Length - 1 do
  begin
    if array2[i] = firstCommon then
      counter1 += 1
    else if array2[i] = secondCommon then
      counter2 += 1
    else if counter1 = 0 then
    begin
      firstCommon := array2[i];
      counter1 += 1;
    end
    else if counter2 = 0 then
    begin
      secondCommon := array2[i];
      counter2 += 1;
    end
    else
    begin
      counter1 -= 1;
      counter2 -= 1;
    end;
  end;

  // Determine third common element
  if counter1 > 0 then
    thirdCommon := firstCommon;

  if counter2 > 0 then
    thirdCommon := secondCommon;

  Result := thirdCommon;
end;

