end.

procedure SortArray(var arr: array of integer);
begin
  var n := arr.Length;
  var minValue := integer.MaxValue;
  var maxValue := integer.MinValue;

  // Найти минимальное и максимальное значения в массиве
  for var i := 0 to n - 1 do
  begin
    if arr[i] < minValue then
      minValue := arr[i];
    if arr[i] > maxValue then
      maxValue := arr[i];
  end;

  // Вычислить диапазон массива
  var range := maxValue - minValue + 1;

  // Создать массив подсчета для хранения частоты каждого числа
  var count := new integer[range];

  // Сохранить частоту каждого числа в массиве подсчета
  for var i := 0 to n - 1 do
    count[arr[i] - minValue] += 1;

  // Перестроить массив подсчета для хранения кумулятивного подсчета
  for var i := 1 to range - 1 do
    count[i] += count[i - 1];

  // Создать временный массив для хранения отсортированного результата
  var temp := new integer[n];

  // Обойти исходный массив справа налево
  for var i := n - 1 downto 0 do
  begin
    // Получить индекс текущего числа в массиве подсчета
    var index := count[arr[i] - minValue] - 1;

    // Поместить текущее число во временный массив по вычисленному индексу
    temp[index] := arr[i];

    // Уменьшить подсчет текущего числа в массиве подсчета
    count[arr[i] - minValue] -= 1;
  end;

  // Скопировать отсортированный результат из временного массива в исходный массив
  for var i := 0 to n - 1 do
    arr[i] := temp[i];
end;

begin
  // Пример использования
  var arr := Arr(3, -1, 2, -1, 5, 3);
  SortArray(arr);
  arr.Print;
end.

