uses System;

const
  ones: array of string = ('zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine');
  teens: array of string = ('ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen');
  tens: array of string = ('', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety');
  thousands: array of string = ('', 'thousand', 'million');

function ConvertNumberToWords(number: decimal): string;
begin
  if (number < -1000000) or (number > 1000000) then
    exit('Number is out of range.');

  if number = 0 then
    exit('zero');

  if number < 0 then
    exit('negative ' + ConvertNumberToWords(Math.Abs(number)));

  var words := '';

  if (number / 1000000) > 0 then
  begin
    words += ConvertNumberToWords(number / 1000000) + ' million ';
    number := number mod 1000000;
  end;

  if (number / 1000) > 0 then
  begin
    words += ConvertNumberToWords(number / 1000) + ' thousand ';
    number := number mod 1000;
  end;

  if (number / 100) > 0 then
  begin
    words += ConvertNumberToWords(number / 100) + ' hundred ';
    number := number mod 100;
  end;

  if number > 0 then
  begin
    if words <> '' then
      words += 'and ';

    if number < 10 then
      words += ones[integer(number)]
    else if number < 20 then
      words += teens[integer(number - 10)]
    else
    begin
      words += tens[integer(number div 10)];
      if (number mod 10) > 0 then
        words += '-' + ones[integer(number mod 10)];
    end;
  end;

  Result := words;
end;

