type
  JsonPropertyAttribute = class(System.Attribute)
    auto property PropName: string;
    constructor(propertyName: string);
    begin
      PropName := propertyName;
    end;
  end;

  CustomAttribute = class(System.Attribute)
  end;

  ExampleClass = class
  public
    [JsonProperty('name')]
    [CustomAttribute]
    auto property Name: string;

    [JsonProperty('age')]
    [CustomAttribute]
    auto property Age: integer;

    [JsonProperty('address')]
    auto property Address: string;

    [JsonProperty('nested')]
    [CustomAttribute]
    auto property Nested: ExampleClass;
  end;

  CustomJsonSerializer = class
  private
    attributeType: System.Type;
    dataType: System.Type;
    excludedValue: object;

    function GetPropertiesWithAttribute(t: System.Type): sequence of System.Reflection.PropertyInfo;
    begin
      Result := t.GetProperties.Where(
        p -> p.GetCustomAttributes(attributeType, False).Length > 0);
    end;

    function SerializeObject(obj: object): string;
    begin
      if obj = nil then
        exit('null');

      var objType := obj.GetType;
      if objType = typeof(string) then
        exit('"' + obj.ToString + '"')
      else if objType.IsPrimitive then
        exit(obj.ToString)
      else
      begin
        var properties := GetPropertiesWithAttribute(objType);
        var dict := new System.Collections.Generic.Dictionary<string, object>;

        foreach var prop in properties do
        begin
          var value := prop.GetValue(obj);
          if (value = nil) or value.Equals(excludedValue) then
            continue;

          if dataType.IsAssignableFrom(prop.PropertyType) then
          begin
            var propertyName := '';
            var attrs := prop.GetCustomAttributes(typeof(JsonPropertyAttribute), False);
            if attrs.Length > 0 then
              propertyName := (attrs[0] as JsonPropertyAttribute).PropName
            else
              propertyName := prop.Name;

            dict[propertyName] := value;
          end;
        end;

        var json := '{'.ToString();
        var first := True;
        foreach var kv in dict do
        begin
          if not first then
            json += ',';
          json += '"' + kv.Key + '":' + SerializeObject(kv.Value);
          first := False;
        end;
        json += '}';

        Result := json;
      end;
    end;

  public
    constructor(attrType, dType: System.Type; excludedVal: object);
    begin
      attributeType := attrType;
      dataType := dType;
      excludedValue := excludedVal;
    end;

    function Serialize(obj: object): string;
    begin
      Result := SerializeObject(obj);
    end;
  end;

begin
  var obj := new ExampleClass;
  obj.Name := 'John';
  obj.Age := 30;
  obj.Address := '123 Main St';
  obj.Nested := new ExampleClass;
  obj.Nested.Name := 'Alice';
  obj.Nested.Age := 25;
  obj.Nested.Address := '456 Second St';

  var serializer := new CustomJsonSerializer(typeof(CustomAttribute), typeof(string), nil);
  var json := serializer.Serialize(obj);
  Println(json);
end.

