function IsPalindrome(s: string): boolean;
begin
  var left := 1;
  var right := s.Length;

  while left < right do
  begin
    // Игнорировать небуквенно-цифровые символы
    while (left < right) and not char.IsLetterOrDigit(s[left]) do
      left += 1;

    while (left < right) and not char.IsLetterOrDigit(s[right]) do
      right -= 1;

    // Сравнить символы без учета регистра
    if s[left].ToLower <> s[right].ToLower then
      exit(False);

    left += 1;
    right -= 1;
  end;

  Result := True;
end;

