function RemoveOccurrences(arr: array of integer; element: integer; 
                            var positions: array of integer; var count: integer): array of integer;
begin
  count := 0;
  var tempPositions := new integer[arr.Length];
  var tempNewArr := new integer[arr.Length];
  var newIndex := 0;

  for var i := 0 to arr.Length - 1 do
    if arr[i] = element then
    begin
      tempPositions[count] := i;
      count += 1;
    end
    else
    begin
      tempNewArr[newIndex] := arr[i];
      newIndex += 1;
    end;

  &Array.Resize(tempNewArr, arr.Length - count);
  &Array.Resize(tempPositions, count);

  positions := tempPositions;
  Result := tempNewArr;
end;

