function GetLongestPalindromeLength(s: string): integer;
begin
  var maxLength := 0;

  for var i := 0 to s.Length - 1 do
    for var j := i to s.Length - 1 do
    begin
      var substring := s.Substring(i, j - i + 1);
      if substring = ReverseString(substring) then
      begin
        var length := substring.Length;
        if length > maxLength then
          maxLength := length;
      end;
    end;

  Result := maxLength;
end;

function GetLongestLowercaseSubstringLength(s: string): integer;
begin
  var maxLength := 0;
  var currentLength := 0;

  for var i := 0 to s.Length - 1 do
    if s[i].IsLower then
    begin
      currentLength += 1;
      if currentLength > maxLength then
        maxLength := currentLength;
    end
    else
      currentLength := 0;

  Result := maxLength;
end;

procedure AnalyzeString(s: string; 
                        var uppercaseCount, lowercaseCount, specialCount: integer; 
                        var characterFrequencies: Dictionary<char, integer>; 
                        var palindromeLength, longestLowercaseSubstringLength: integer; 
                        var sortedCharacters: string);
begin
  uppercaseCount := 0;
  lowercaseCount := 0;
  specialCount := 0;
  var charFrequencies := new Dictionary<char, integer>;

  foreach var c in s do
  begin
    if c.IsUpper then
      uppercaseCount += 1
    else if c.IsLower then
      lowercaseCount += 1
    else
      specialCount += 1;

    if charFrequencies.ContainsKey(c) then
      charFrequencies[c] += 1
    else
      charFrequencies[c] := 1;
  end;

  palindromeLength := GetLongestPalindromeLength(s);
  longestLowercaseSubstringLength := GetLongestLowercaseSubstringLength(s);

  var chars := s.ToCharArray;
  &Array.Sort(chars, (c1, c2) -> charFrequencies[c2].CompareTo(charFrequencies[c1]));
  sortedCharacters := new string(chars);

  characterFrequencies := charFrequencies;
end;

begin
  var input := 'Hello, World!';

  var uppercaseCount, lowercaseCount, specialCount: integer;
  var characterFrequencies: Dictionary<char, integer>;
  var palindromeLength, longestLowercaseSubstringLength: integer;
  var sortedCharacters: string;

  AnalyzeString(input, uppercaseCount, lowercaseCount, specialCount, 
                characterFrequencies, palindromeLength, longestLowercaseSubstringLength, 
                sortedCharacters);

