function GenerateRandomString(): string;
begin
  var rnd := new System.Random;
  var sb := new System.Text.StringBuilder;
  var consonantCount := 0;
  var uppercaseCount := 0;
  var digitCount := 0;

  while sb.Length < 10 do
  begin
    var randomChar := char(rnd.Next('A'.Code, 'Z'.Code + 1));

    if (not IsVowel(randomChar)) and (randomChar.ToLower <> 'y') then
    begin
      sb.Append(randomChar);

      if randomChar.IsUpper then
        uppercaseCount += 1;

      if randomChar.IsDigit then
        digitCount += 1;

      if not IsVowel(randomChar) then
        consonantCount += 1;
    end;
  end;

  while consonantCount < 3 do
  begin
    var index := rnd.Next(sb.Length);
    var randomChar := char(rnd.Next('A'.Code, 'Z'.Code + 1));

    if (not IsVowel(randomChar)) and (randomChar.ToLower <> 'y') and randomChar.IsUpper then
    begin
      sb[index] := randomChar;
      consonantCount += 1;
    end;
  end;

  while uppercaseCount < 2 do
  begin
    var index := rnd.Next(sb.Length);
    var randomChar := char(rnd.Next('A'.Code, 'Z'.Code + 1));

    if (not IsVowel(randomChar)) and (randomChar.ToLower <> 'y') and randomChar.IsUpper then
    begin
      sb[index] := randomChar;
      uppercaseCount += 1;
    end;
  end;

  while digitCount < 1 do
  begin
    var index := rnd.Next(sb.Length);
    var randomChar := char(rnd.Next('0'.Code, '9'.Code + 1));

    if (not IsVowel(randomChar)) and (randomChar.ToLower <> 'y') and randomChar.IsDigit then
    begin
      sb[index] := randomChar;
      digitCount += 1;
    end;
  end;

  Result := sb.ToString;
end;

