procedure Merge(strings: array of string; left, mid, right: integer); forward;

function CompareStrings(a, b: string): integer; forward;

procedure MergeSort(strings: array of string; left, right: integer);
begin
  if left < right then
  begin
    var mid := (left + right) div 2;

    MergeSort(strings, left, mid);
    MergeSort(strings, mid + 1, right);

    Merge(strings, left, mid, right);
  end;
end;

procedure Merge(strings: array of string; left, mid, right: integer);
begin
  var n1 := mid - left + 1;
  var n2 := right - mid;

  var leftArray := new string[n1];
  var rightArray := new string[n2];

  System.Array.Copy(strings, left, leftArray, 0, n1);
  System.Array.Copy(strings, mid + 1, rightArray, 0, n2);

  var i := 0;
  var j := 0;
  var k := left;

  while (i < n1) and (j < n2) do
  begin
    if CompareStrings(leftArray[i], rightArray[j]) <= 0 then
    begin
      strings[k] := leftArray[i];
      i += 1;
    end
    else
    begin
      strings[k] := rightArray[j];
      j += 1;
    end;
    k += 1;
  end;

  while i < n1 do
  begin
    strings[k] := leftArray[i];
    i += 1;
    k += 1;
  end;

  while j < n2 do
  begin
    strings[k] := rightArray[j];
    j += 1;
    k += 1;
  end;
end;

function CompareStrings(a, b: string): integer;
begin
  var minLength := Min(a.Length, b.Length);

  for var i := 1 to minLength do
  begin
    if a[i] <> b[i] then
    begin
      if a[i].IsDigit and (not b[i].IsDigit) then
        exit(-1)
      else if (not a[i].IsDigit) and b[i].IsDigit then
        exit(1)
      else if a[i] < b[i] then
        exit(-1)
      else
        exit(1);
    end;
  end;

  Result := a.Length.CompareTo(b.Length);
end;

procedure SortStrings(var strings: array of string);
begin
  MergeSort(strings, 0, strings.Length - 1);
end;

