function MergeSortDescending(arr: array of integer): array of integer;
begin
  if arr.Length <= 1 then
  begin
    Result := arr;
    exit;
  end;

  var mid := arr.Length div 2;
  var left := new integer[mid];
  var right := new integer[arr.Length - mid];

  System.Array.Copy(arr, 0, left, 0, mid);
  System.Array.Copy(arr, mid, right, 0, arr.Length - mid);

  left := MergeSortDescending(left);
  right := MergeSortDescending(right);

  Result := MergeDescending(left, right);
end;

function MergeDescending(left, right: array of integer): array of integer;
begin
  var leftIndex := 0;
  var rightIndex := 0;
  var resultIndex := 0;
  Result := new integer[left.Length + right.Length];

  while (leftIndex < left.Length) and (rightIndex < right.Length) do
  begin
    if left[leftIndex] >= right[rightIndex] then
    begin
      Result[resultIndex] := left[leftIndex];
      leftIndex += 1;
    end
    else
    begin
      Result[resultIndex] := right[rightIndex];
      rightIndex += 1;
    end;
    resultIndex += 1;
  end;

  while leftIndex < left.Length do
  begin
    Result[resultIndex] := left[leftIndex];
    leftIndex += 1;
    resultIndex += 1;
  end;

  while rightIndex < right.Length do
  begin
    Result[resultIndex] := right[rightIndex];
    rightIndex += 1;
    resultIndex += 1;
  end;
end;

