function LongestIncreasingSubsequence(nums: array of integer): integer;
begin
  var tails := new integer[nums.Length];
  var len := 1;

  tails[0] := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] < tails[0] then
      tails[0] := nums[i]
    else if nums[i] > tails[len - 1] then
    begin
      tails[len] := nums[i];
      len += 1;
    end
    else
    begin
      var l := 0;
      var r := len - 1;

      while l < r do
      begin
        var mid := l + (r - l) div 2;
        if tails[mid] >= nums[i] then
          r := mid
        else
          l := mid + 1;
      end;

      tails[l] := nums[i];
    end;
  end;

  Result := len;
end;

