function BinarySearch(arr: array [,] of integer; key: integer; left, right: integer; var comparisons: integer): integer;
begin
  if left > right then
  begin
    Result := -1;
    exit;
  end;

  var mid := (left + right) div 2;
  var midValue := arr[mid div arr.GetLength(1), mid mod arr.GetLength(1)];

  if midValue = key then
    Result := mid
  else if midValue > key then
  begin
    comparisons += 1;
    Result := BinarySearch(arr, key, left, mid - 1, comparisons);
  end
  else
  begin
    comparisons += 1;
    Result := BinarySearch(arr, key, mid + 1, right, comparisons);
  end;
end;

