type
  CompoundInterestCalculator = class
  private
    _principalAmount: real;
    _interestRate: real;
    _numberOfYears: integer;
  public
    constructor Create(aPrincipalAmount, aInterestRate: real; aNumberOfYears: integer);
    begin
      if aPrincipalAmount <= 0 then
        raise new System.ArgumentException('Principal amount must be positive.');
      _principalAmount := aPrincipalAmount;

      _interestRate := aInterestRate;

      if aNumberOfYears <= 0 then
        raise new System.ArgumentException('Number of years must be a positive integer.');
      _numberOfYears := aNumberOfYears;
    end;

    procedure SetPrincipalAmount(value: real);
    begin
      if value <= 0 then
        raise new System.ArgumentException('Principal amount must be positive.');
      _principalAmount := value;
    end;

    procedure SetInterestRate(value: real);
    begin
      if (value < 0) or (value > 100) then
        raise new System.ArgumentException('Interest rate must be between 0 and 100%.');
      _interestRate := value;
    end;

    procedure SetNumberOfYears(value: integer);
    begin
      if value <= 0 then
        raise new System.ArgumentException('Number of years must be a positive integer.');
      _numberOfYears := value;
    end;

    property PrincipalAmount: real read _principalAmount write SetPrincipalAmount;
    property InterestRate: real read _interestRate write SetInterestRate;
    property NumberOfYears: integer read _numberOfYears write SetNumberOfYears;

    function CalculateInterest: real;
    begin
      var interestAmount := _principalAmount * Power(1 + (_interestRate / 100), _numberOfYears);
      Result := interestAmount - _principalAmount;
    end;
  end;

