function StringToInteger(s: string): integer;
begin
  s := s.Trim;
  if s = '' then
  begin
    Result := 0;
    exit;
  end;

  var isNegative := false;
  if s[1] = '-' then
  begin
    isNegative := true;
    s := s.Substring(1);
  end
  else if s[1] = '+' then
    s := s.Substring(1);

  var res := 0;
  var maxLength := isNegative ? 11 : 10;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if (c >= '0') and (c <= '9') then
    begin
      res := res * 10 + (Ord(c) - Ord('0'));
      if res.ToString.Length > maxLength then
        break;
    end
    else
    begin
      Result := 0;
      exit;
    end;
  end;

  if isNegative then
    res := -res;

  if res < integer.MinValue then
    Result := integer.MinValue
  else if res > integer.MaxValue then
    Result := integer.MaxValue
  else
    Result := res;
end;

