type
  TwoDimensionalArraySearch = class
    public
      function SearchValue(arr: array[,] of integer; target: integer): (integer, integer);
      begin
        var numRows := arr.GetLength(0);
        var numCols := arr.GetLength(1);
        var low := 0;
        var high := numRows * numCols - 1;

        while low <= high do
        begin
          var mid := (low + high) div 2;
          var row := mid div numCols;
          var col := mid mod numCols;
          var value := arr[row, col];

          if value = target then
          begin
            Result := (row, col);
            exit;
          end
          else if value < target then
            low := mid + 1
          else
            high := mid - 1;
        end;
        Result := (-1, -1);
      end;

      function SearchRow(arr: array[,] of integer; target: integer): integer;
      begin
        var numRows := arr.GetLength(0);
        var numCols := arr.GetLength(1);

        for var row := 0 to numRows - 1 do
        begin
          var low := 0;
          var high := numCols - 1;

          while low <= high do
          begin
            var mid := (low + high) div 2;
            var value := arr[row, mid];

            if value = target then
            begin
              Result := row;
              exit;
            end
            else if value < target then
              low := mid + 1
            else
              high := mid - 1;
          end;
        end;
        Result := -1;
      end;

      function SearchColumn(arr: array[,] of integer; target: integer): integer;
      begin
        var numRows := arr.GetLength(0);
        var numCols := arr.GetLength(1);

        for var col := 0 to numCols - 1 do
        begin
          var low := 0;
          var high := numRows - 1;

          while low <= high do
          begin
            var mid := (low + high) div 2;
            var value := arr[mid, col];

            if value = target then
            begin
              Result := col;
              exit;
            end
            else if value < target then
              low := mid + 1
            else
              high := mid - 1;
          end;
        end;
        Result := -1;
      end;

      function SearchSubmatrix(arr: array[,] of integer; submatrix: array[,] of integer): (integer, integer);
      begin
        var numRows := arr.GetLength(0);
        var numCols := arr.GetLength(1);
        var subNumRows := submatrix.GetLength(0);
        var subNumCols := submatrix.GetLength(1);

        for var row := 0 to numRows - subNumRows do
          for var col := 0 to numCols - subNumCols do
          begin
            var found := true;

            for var subRow := 0 to subNumRows - 1 do
              for var subCol := 0 to subNumCols - 1 do
                if arr[row + subRow, col + subCol] <> submatrix[subRow, subCol] then
                begin
                  found := false;
                  break;
                end;

            if found then
            begin
              Result := (row, col);
              exit;
            end;
          end;
        Result := (-1, -1);
      end;
  end;

begin
  var search := new TwoDimensionalArraySearch;
  var arr := new integer[3,3]((1,2,3),(4,5,6),(7,8,9));
  var target := 5;

  var position := search.SearchValue(arr, target);
  Println($'Target {target} found at position: ({position.Item1}, {position.Item2})');

  var row := search.SearchRow(arr, target);
  Println($'Target {target} found at row: {row}');

  var col := search.SearchColumn(arr, target);
  Println($'Target {target} found at column: {col}');

  var submatrix := new integer[2,2]((5,6),(8,9));
  var submatrixPosition := search.SearchSubmatrix(arr, submatrix);
  Println($'Submatrix found at position: ({submatrixPosition.Item1}, {submatrixPosition.Item2})');
end.

