function FindRoots(a, b, c, d: real): array of Complex;
begin
  var roots := new Complex[3];

  var discriminant := (new Complex(b, 0)) * (new Complex(b, 0)) - (3 * (new Complex(a, 0)) * (new Complex(c, 0)));
  var sqrtDiscriminant := Complex.Sqrt(discriminant);

  var alpha := (2 * b * b * b - 9 * a * b * c + 27 * a * a * d + Complex.Pow((sqrtDiscriminant + new Complex(b * b - 3 * a * c, 0)) / (2 * sqrtDiscriminant), 3)) / (2 * Complex.Pow(sqrtDiscriminant, 3));
  var omega := new Complex(-0.5, Sqrt(3) / 2);

  for var k := 0 to 2 do
  begin
    var root := Complex.Pow(alpha + omega * Complex.Pow(sqrtDiscriminant, k), 1.0 / 3.0);
    roots[k] := root - (new Complex(b, 0) / (3 * (new Complex(a, 0))));
  end;

  Result := roots;
end;

