procedure SortWithDuplicates(var numbers: array of integer);
begin
  &Array.Sort(numbers);

  var duplicates := new integer[numbers.Length];
  var duplicatesIndex := 0;

  for var i := 1 to numbers.Length - 1 do
    if numbers[i] = numbers[i - 1] then
    begin
      duplicates[duplicatesIndex] := numbers[i];
      duplicatesIndex += 1;
      numbers[i] := -1;
    end;

  var sortedDuplicates := new integer[duplicatesIndex];
  &Array.Copy(duplicates, sortedDuplicates, duplicatesIndex);

  &Array.Resize(numbers, numbers.Length - duplicatesIndex);
  &Array.Copy(sortedDuplicates, 0, numbers, numbers.Length, duplicatesIndex);
end;

