    var prev1: int64 := 1;
    var prev2: int64 := 1;
    var current: int64 := 0;

    for var i := 3 to n do
    begin
      current := prev1 + prev2;
      prev2 := prev1;
      prev1 := current;
    end;

    Result := current;
  end;
end;

