type
  Graph = class
  private
    adjacencyList: Dictionary<integer, List<integer>>;

    procedure DFSUtil(vertex: integer; var visited: array of boolean);
    begin
      visited[vertex] := true;
      Write(vertex, ' ');

      foreach var neighbor in adjacencyList[vertex] do
        if not visited[neighbor] then
          DFSUtil(neighbor, visited);
    end;

  public
    constructor Create;
    begin
      adjacencyList := new Dictionary<integer, List<integer>>;
    end;

    procedure AddVertex(vertex: integer);
    begin
      if not adjacencyList.ContainsKey(vertex) then
        adjacencyList[vertex] := new List<integer>;
    end;

    procedure AddEdge(fromVertex, toVertex: integer);
    begin
      if adjacencyList.ContainsKey(fromVertex) and adjacencyList.ContainsKey(toVertex) then
        adjacencyList[fromVertex].Add(toVertex)
      else
        raise new System.ArgumentException('Both vertices must exist in the graph');
    end;

    procedure DFS(startVertex: integer);
    begin
      var visited := new boolean[adjacencyList.Count + 1];
      DFSUtil(startVertex, visited);
    end;

    procedure BFS(startVertex: integer);
    begin
      var visited := new boolean[adjacencyList.Count + 1];
      var queue := new Queue<integer>;

      visited[startVertex] := true;
      queue.Enqueue(startVertex);

      while queue.Count > 0 do
      begin
        var vertex := queue.Dequeue;
        Write(vertex, ' ');

        foreach var neighbor in adjacencyList[vertex] do
          if not visited[neighbor] then
          begin
            visited[neighbor] := true;
            queue.Enqueue(neighbor);
          end;
      end;
    end;
  end;

