function IsNarcissisticNumber(number: integer): boolean;
begin
  var digitCount := number.ToString.Length;
  if not IsPrime(digitCount) then
  begin
    Result := false;
    exit;
  end;

  var sum := 0;
  var temp := number;
  while temp > 0 do
  begin
