function BinarySearchFirstOccurrence(arr: array of integer; target, low, high: integer): integer;
begin
  if low > high then
    Result := -1
  else
  begin
    var mid := low + (high - low) div 2;

    if (arr[mid] = target) and ((mid = 0) or (arr[mid - 1] < target)) then
      Result := mid
    else if arr[mid] >= target then
      Result := BinarySearchFirstOccurrence(arr, target, low, mid - 1)
    else
      Result := BinarySearchFirstOccurrence(arr, target, mid + 1, high);
  end;
end;

function BinarySearchLastOccurrence(arr: array of integer; target, low, high: integer): integer;
begin
  if low > high then
    Result := -1
  else
  begin
    var mid := low + (high - low) div 2;

    if (arr[mid] = target) and ((mid = arr.Length - 1) or (arr[mid + 1] > target)) then
      Result := mid
    else if arr[mid] > target then
      Result := BinarySearchLastOccurrence(arr, target, low, mid - 1)
    else
      Result := BinarySearchLastOccurrence(arr, target, mid + 1, high);
  end;
end;

function BinarySearchFirstLastOccurrence(arr: array of integer; target: integer): (integer, integer);
begin
  var firstOccurrence := BinarySearchFirstOccurrence(arr, target, 0, arr.Length - 1);
  var lastOccurrence := BinarySearchLastOccurrence(arr, target, 0, arr.Length - 1);
  Result := (firstOccurrence, lastOccurrence);
end;

