procedure BubbleSort(var arr: array of string);
begin
  var n := arr.Length;
  var swapped: boolean;

  for var i := 0 to n - 2 do
  begin
    swapped := false;
    for var j := 0 to n - i - 2 do
    begin
      if string.Compare(arr[j], arr[j + 1]) > 0 then
      begin
        // Swap arr[j] and arr[j+1]
        var temp := arr[j];
        arr[j] := arr[j + 1];
        arr[j + 1] := temp;
        swapped := true;
      end;
    end;

    // If no two elements were swapped in the inner loop, then the array is already sorted
    if not swapped then
    begin
      break;
    end;
  end;
end;

