function AreAnagrams(str1, str2: string): boolean;
begin
  // Ignore leading and trailing spaces
  str1 := str1.Trim;
  str2 := str2.Trim;

  // Convert to lowercase
  str1 := str1.ToLower;
  str2 := str2.ToLower;

  // Check if both strings are non-empty
  if (string.IsNullOrEmpty(str1)) or (string.IsNullOrEmpty(str2)) then
  begin
    exit(false);
  end;

  // Check if both strings have the same length
  if str1.Length <> str2.Length then
  begin
    exit(false);
  end;

  // Check if both strings only contain lowercase letters
  if not str1.All(char.IsLower) or not str2.All(char.IsLower) then
  begin
    exit(false);
  end;

  // Count the frequency of each letter in both strings
