function CheckIfAnagrams(str1, str2: string): boolean;
begin
  // Remove special characters and leading/trailing spaces
  var cleanStr1 := (new string(str1.Where(c -> char.IsLetter(c)).ToArray)).ToLower.Trim;
  var cleanStr2 := (new string(str2.Where(c -> char.IsLetter(c)).ToArray)).ToLower.Trim;

  // If lengths are different, the strings can't be anagrams
  if cleanStr1.Length <> cleanStr2.Length then
    exit(false);

  // Create frequency arrays for each string
  var freq1 := new integer[26];
  var freq2 := new integer[26];

  // Count the frequency of each character in the first string
  foreach var c in cleanStr1 do
    freq1[ord(c) - ord('a')] += 1;

  // Count the frequency of each character in the second string
  foreach var c in cleanStr2 do
    freq2[ord(c) - ord('a')] += 1;

  // Compare the frequency arrays with O(n^2) complexity
  for var i := 0 to 25 do
  begin
    var found := false;
    for var j := 0 to 25 do
    begin
      if (freq1[i] = freq2[j]) and (i = j) then
      begin
        found := true;
        break;
      end;
    end;

    if not found then
      exit(false);
  end;

  Result := true;
end;

