procedure ShuffleArray(var arr: array of integer);
begin
  var random := new Random;
  var length := arr.Length;

  // Shuffle the array
  for var i := 0 to length - 1 do
  begin
    // Generate a random index
    var randomIndex := random.Next(i, length);

    // Swap the current element with the element at the random index
    var temp := arr[randomIndex];
    arr[randomIndex] := arr[i];
    arr[i] := temp;
  end;

  // Rearrange the array so that odd numbers come before even numbers
  var left := 0;
  var right := length - 1;

  while left < right do
  begin
    // Find the next even number from the left side
    while (left < right) and (arr[left] mod 2 = 1) do
    begin
      left += 1;
    end;

    // Find the next odd number from the right side
    while (left < right) and (arr[right] mod 2 = 0) do
    begin
      right -= 1;
    end;

    // Swap the even number with the odd number
    var temp := arr[left];
    arr[left] := arr[right];
    arr[right] := temp;
  end;
end;

