function CalculateArea(radiusString: string): string;
begin
  if string.IsNullOrWhiteSpace(radiusString) then
  begin
    exit('Error: No radius value provided.');
  end;

  var radius: real;
  if not real.TryParse(radiusString, radius) then
  begin
    exit('Error: Invalid radius value.');
  end;

  if radius < 0 then
  begin
    exit('Error: Negative radius value is not allowed.');
  end;

  if radius = 0 then
  begin
    exit('0');
  end;

  // Check precision
  if radiusString.Contains('.') then
  begin
    var decimalParts := radiusString.Split('.');
    if decimalParts.Length > 1 then
    begin
      var decimalPart := decimalParts[1];
      if decimalPart.Length > 15 then
      begin
        exit('Error: Precision exceeds limit.');
      end;
      if decimalPart.Length < 2 then
      begin
        exit('Error: Precision is too low.');
      end;
    end;
  end;

  var area := Pi * radius * radius;

  if real.IsInfinity(area) then
  begin
    exit('Error: Result exceeds maximum value.');
  end;

  // Handle different output formats based on input
  if radiusString.Contains('.') and not radiusString.EndsWith('.0') then
  begin
    Result := round(area, 2).ToString;
  end
  else
  begin
    Result := round(area).ToString;
  end;
end;

