function GetCharacterFrequencies(strVal: string): System.Collections.Generic.Dictionary<char, integer>;
begin
  Result := new System.Collections.Generic.Dictionary<char, integer>;

  foreach var ch in strVal do
  begin
    if Result.ContainsKey(ch) then
    begin
      Result[ch] += 1;
    end
    else
    begin
      Result[ch] := 1;
    end;
  end;
end;

function AreDictionariesEqual(dict1, dict2: System.Collections.Generic.Dictionary<char, integer>): boolean;
begin
  if dict1.Count <> dict2.Count then
  begin
    exit(false);
  end;

  foreach var kvp in dict1 do
  begin
    var keyVal := kvp.Key;
    var valueVal := kvp.Value;

    if not dict2.ContainsKey(keyVal) or (dict2[keyVal] <> valueVal) then
    begin
      exit(false);
    end;
  end;

  Result := true;
end;

function IsPermutation(str1, str2: string): boolean;
begin
  // Step 1: Remove whitespace characters and punctuation marks
  var cleanedStr1 := RemoveNonAlphanumeric(str1);
  var cleanedStr2 := RemoveNonAlphanumeric(str2);

  // Step 2: Check if the cleaned strings have the same length
  if cleanedStr1.Length <> cleanedStr2.Length then
  begin
    exit(false);
  end;

  // Step 3: Convert the strings to lowercase for case insensitivity
  cleanedStr1 := cleanedStr1.ToLower;
  cleanedStr2 := cleanedStr2.ToLower;

  // Step 4: Create character frequency dictionaries for both strings
  var freqDict1 := GetCharacterFrequencies(cleanedStr1);
  var freqDict2 := GetCharacterFrequencies(cleanedStr2);

  // Step 5: Check if the character frequency dictionaries are equal
  Result := AreDictionariesEqual(freqDict1, freqDict2);
end;

