function IsValidTriangle(side1, side2, side3: real): boolean;
begin
  Result := (side1 + side2 > side3) and (side1 + side3 > side2) and (side2 + side3 > side1);
end;

function CalculateArea(side1, side2, side3: real): real;
begin
  var s := (side1 + side2 + side3) / 2;
  Result := sqrt(s * (s - side1) * (s - side2) * (s - side3));
end;

function IsEquilateral(side1, side2, side3: real): boolean;
begin
  Result := (side1 = side2) and (side2 = side3);
end;

function IsIsosceles(side1, side2, side3: real): boolean;
begin
  Result := (side1 = side2) or (side1 = side3) or (side2 = side3);
end;

function IsScalene(side1, side2, side3: real): boolean;
begin
  Result := (side1 <> side2) and (side1 <> side3) and (side2 <> side3);
end;

function IsRightAngled(side1, side2, side3: real): boolean;
begin
  var a := side1 * side1;
  var b := side2 * side2;
  var c := side3 * side3;

  Result := (a = b + c) or (b = a + c) or (c = a + b);
end;

function IsObtuseAngled(side1, side2, side3: real): boolean;
begin
  var a := side1 * side1;
  var b := side2 * side2;
  var c := side3 * side3;

  Result := (a > b + c) or (b > a + c) or (c > a + b);
end;

function IsAcuteAngled(side1, side2, side3: real): boolean;
begin
  Result := not IsRightAngled(side1, side2, side3) and not IsObtuseAngled(side1, side2, side3);
end;

function IsDegenerate(side1, side2, side3: real): boolean;
begin
  Result := (side1 + side2 = side3) or (side1 + side3 = side2) or (side2 + side3 = side1);
end;

