procedure BubbleSort(var numbers: array of integer);
begin
  var length := numbers.Length;

  for var i := 0 to length - 2 do
  begin
    for var j := 0 to length - i - 2 do
    begin
      if numbers[j] > numbers[j + 1] then
      begin
        var temp := numbers[j];
        numbers[j] := numbers[j + 1];
        numbers[j + 1] := temp;
      end;
    end;
  end;
end;

function CalculateMedian(numbers: array of integer): real;
begin
  var length := numbers.Length;

  // Handle empty array
  if length = 0 then
  begin
    exit(0);
  end;

  // Sort the array
  BubbleSort(numbers);

  // Handle array with one element
  if length = 1 then
  begin
    exit(numbers[0]);
  end;

  // Calculate median
  var middleIndex := length div 2;
  if length mod 2 = 1 then
  begin
    // Array has odd number of elements
    Result := numbers[middleIndex];
  end
  else
  begin
    // Array has even number of elements
    Result := (numbers[middleIndex - 1] + numbers[middleIndex]) / 2.0;
  end;
end;

