  var numbers := Arr(5, 2, 9, 1, 7);
  var median := CalculateMedian(numbers);
  Println(median); // Output: 5
end.

procedure QuickSort(var arr: array of integer; low, high: integer); forward;

function Partition(var arr: array of integer; low, high: integer): integer;
begin
  var pivot := arr[high];
  var i := low - 1;

  for var j := low to high - 1 do
  begin
    if arr[j] >= pivot then
    begin
      i += 1;
      var temp := arr[i];
      arr[i] := arr[j];
      arr[j] := temp;
    end;
  end;

  var temp2 := arr[i + 1];
  arr[i + 1] := arr[high];
  arr[high] := temp2;
  Result := i + 1;
end;

procedure QuickSort(var arr: array of integer; low, high: integer);
begin
  if low < high then
  begin
    var partitionIndex := Partition(arr, low, high);
    QuickSort(arr, low, partitionIndex - 1);
    QuickSort(arr, partitionIndex + 1, high);
  end;
end;

procedure SortDescending(var arr: array of integer);
begin
  if arr.Length > 0 then
  begin
    QuickSort(arr, 0, arr.Length - 1);
  end;
end;

