function CountUniqueConsecutiveCharacters(input: string): integer;
begin
  if input = nil then
  begin
    exit(0);
  end;

  var count := 0;
  var previousCharacter: char? := nil;
  var index := 1;

  while index <= input.Length do
  begin
    var currentChar := input[index];
    if char.IsLetter(currentChar) then
    begin
      var lowerChar := char.ToLower(currentChar);

      if (previousCharacter = nil) or (lowerChar <> previousCharacter) then
      begin
        count += 1;
      end;

      previousCharacter := lowerChar;
    end;

    index += 1;
  end;

  Result := count;
end;

