procedure ReverseArray(var arr: array of integer);
begin
  var left := 0;
  var right := arr.Length - 1;

  while left < right do
  begin
    // Swap elements at left and right indices
    var temp := arr[left];
    arr[left] := arr[right];
    arr[right] := temp;

    // Move towards the center of the array
    left += 1;
    right -= 1;
  end;
end;

