function CalculateRectangleArea(length, width: real): integer;
begin
  if (length <= 0) or (width <= 0) or (length >= 1000) or (width >= 1000) then
  begin
    raise new System.ArgumentException('Rectangle dimensions should be positive integers and less than 1000.');
  end;

  var roundedLength := round(length);
  var roundedWidth := round(width);

  Result := roundedLength * roundedWidth;
