function RemoveAdjacentDuplicates(strVal: string): string;
begin
  var outputStr := '';
  var len := strVal.Length;
  var i := 0;

  while i < len do
  begin
    outputStr += strVal[i];

    // Skip adjacent duplicates
    var j := i + 1;
    while (j < len) and (strVal[j] = strVal[i]) do
      j += 1;

    i := j;
  end;

  Result := outputStr;
end;

