procedure Swap(var arr: array of integer; i, j: integer);
begin
  var temp := arr[i];
  arr[i] := arr[j];
  arr[j] := temp;
end;

function Partition(var arr: array of integer; low, high: integer): integer;
begin
  var pivot := arr[high];
  var i := low - 1;

  for var j := low to high - 1 do
  begin
    if arr[j] >= pivot then
    begin
      i += 1;
      Swap(arr, i, j);
    end;
  end;

  Swap(arr, i + 1, high);
  Result := i + 1;
end;

procedure QuickSort(var arr: array of integer; low, high: integer);
begin
  if low < high then
  begin
    var partitionIndex := Partition(arr, low, high);
    QuickSort(arr, low, partitionIndex - 1);
    QuickSort(arr, partitionIndex + 1, high);
  end;
end;

