function CountVowels(str: string): integer;
begin
  var vowels := 'aeiou';
  var count := 0;
  var ignoreNextConsonant := false;
  var ignoreVowelsInParentheses := false;

  for var i := 1 to str.Length do
  begin
    var c := char.ToLower(str[i]);

    if c = '(' then
    begin
      ignoreVowelsInParentheses := true;
    end
    else if c = ')' then
    begin
      ignoreVowelsInParentheses := false;
    end
    else if ignoreVowelsInParentheses and (vowels.IndexOf(c) >= 0) then
    begin
      // Ignore vowels within parentheses
      continue;
    end
    else if vowels.IndexOf(c) >= 0 then
    begin
      if ignoreNextConsonant then
      begin
        ignoreNextConsonant := false;
        continue;
      end;

      count += 1;

      // Check if the next character is a consonant
      if (i < str.Length) and (vowels.IndexOf(char.ToLower(str[i + 1])) < 0) then
      begin
        ignoreNextConsonant := true;
      end;
    end;
  end;

  Result := count;
end;

begin
  var str := 'This is a (sample) string.';
  var vowelCount := CountVowels(str);
  Println('Total Vowels: ', vowelCount);
end.

