function BinarySearch(arr: array of integer; left, right, target: integer): integer;
begin
  while left <= right do
  begin
    var mid := left + (right - left) div 2;

    if arr[mid] = target then
      Result := mid
    else if arr[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := left;
end;

function LongestIncreasingSubsequence(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n];
  var len := 1;

  dp[0] := arr[0];

  for var i := 1 to n - 1 do
  begin
    if arr[i] < dp[0] then
      dp[0] := arr[i]
    else if arr[i] >= dp[len - 1] then
    begin
      dp[len] := arr[i];
      len += 1;
    end
    else
    begin
      var pos := BinarySearch(dp, 0, len - 1, arr[i]);
      dp[pos] := arr[i];
    end;
  end;

  Result := len;
end;

