procedure MergeDescending(var arr: array of integer; left, right: array of integer);
begin
  var i := 0;
  var j := 0;
  var k := 0;

  while (i < left.Length) and (j < right.Length) do
  begin
    if left[i] > right[j] then
    begin
      arr[k] := left[i];
      i += 1;
    end
    else
    begin
      arr[k] := right[j];
      j += 1;
    end;
    k += 1;
  end;

  while i < left.Length do
  begin
    arr[k] := left[i];
    i += 1;
    k += 1;
  end;

  while j < right.Length do
  begin
    arr[k] := right[j];
    j += 1;
    k += 1;
  end;
end;

procedure MergeSortDescending(var arr: array of integer);
begin
  if arr.Length <= 1 then
    exit;

  var mid := arr.Length div 2;
  var left := new integer[mid];
  var right := new integer[arr.Length - mid];

  &Array.Copy(arr, 0, left, 0, mid);
  &Array.Copy(arr, mid, right, 0, arr.Length - mid);

  MergeSortDescending(left);
  MergeSortDescending(right);

  MergeDescending(arr, left, right);
end;

